from billing.invoice import invoice_total_cents, line_total_cents


def test_line_total():
    assert line_total_cents(250, 4) == 1000


def test_invoice_total():
    assert invoice_total_cents([(250, 4), (99, 1)]) == 1099


def test_empty_invoice():
    assert invoice_total_cents([]) == 0
